/* Generated by scripts/build.mjs. No user data enters this cache. */
const BUILD='0.16.1-25cd51e6775d274b';
const PREFIX='orbit-mobile:'+self.registration.scope+':';
const CACHE=PREFIX+BUILD;
const ASSETS=['index.html','igra.html','manifest.webmanifest','icon-192.png','icon-512.png','apple-touch-icon.png','downloads/zljixOS.html'].map(file=>new URL(file,self.registration.scope).href);
const INDEX=ASSETS[0];
self.addEventListener('install',event=>{
  event.waitUntil((async()=>{
    const cache=await caches.open(CACHE);
    try{await cache.addAll(ASSETS.map(url=>new Request(url,{cache:'reload'})));}
    catch(error){await caches.delete(CACHE);throw error;}
    // No skipWaiting: an update must not replace a running lesson.
  })());
});
self.addEventListener('activate',event=>{
  event.waitUntil((async()=>{
    for(const key of await caches.keys())if(key.startsWith(PREFIX)&&key!==CACHE)await caches.delete(key);
    await self.clients.claim();
  })());
});
self.addEventListener('fetch',event=>{
  const request=event.request,url=new URL(request.url),scope=new URL(self.registration.scope);
  if(request.method!=='GET'||url.origin!==scope.origin||!url.pathname.startsWith(scope.pathname))return;
  const isHome=request.mode==='navigate'&&[scope.pathname,new URL(INDEX).pathname,new URL('igra.html',scope).pathname].includes(url.pathname);
  const key=isHome?INDEX:(ASSETS.includes(url.href)?url.href:null);
  if(!key)return;
  event.respondWith((async()=>{
    const cache=await caches.open(CACHE);
    // A deliberate new navigation can receive a new edition. Never reload an
    // in-progress page automatically; keep the installed copy for offline use.
    if(isHome){
      const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),3500);
      try{const response=await fetch(new Request(request.url,{cache:'no-cache',signal:controller.signal}));if(response.ok&&response.headers.get('content-type')?.includes('text/html'))return response;}
      catch{/* Offline or timeout: use the last completely installed edition. */}
      finally{clearTimeout(timer);}
    }
    return (await cache.match(key))||fetch(request);
  })());
});
self.addEventListener('message',event=>{
  if(event.data?.type==='ZLJIX_APPLY_UPDATE'){event.waitUntil(self.skipWaiting());return;}
  if(event.data?.type!=='ORBIT_OFFLINE_STATUS'||!event.ports?.[0])return;
  event.waitUntil((async()=>{
    let ready=false;
    try{const cache=await caches.open(CACHE);ready=(await Promise.all(ASSETS.map(url=>cache.match(url)))).every(Boolean);}catch{}
    event.ports[0].postMessage({type:'ORBIT_OFFLINE_STATUS',ready,downloadReady:ready,build:BUILD});
  })());
});
